buildGradleAdditions.insert:
android { useLibrary 'android.car' }
dependencies {
    implementation files('libs/pleosbridge.aar')
    implementation 'ai.pleos.playground:Vehicle:2.3.2'
    implementation 'org.jetbrains.kotlin:kotlin-stdlib:2.2.10'
}

gameActivityClassAdditions.insert:
public String AndroidThunkJava_PleosSnapshot() { return PleosRuntime.snapshot(); }
public String AndroidThunkJava_PleosFeedback(String command) { return PleosRuntime.feedback(command); }
public boolean AndroidThunkJava_BPInitializeAudioFocus() {
    // UE creates/tracks this request when its first native listener registers,
    // but ignores the initial result. Reuse that request to report grant/denial.
    if (audioFocusRequest == null || android.os.Build.VERSION.SDK_INT < 26) return false;
    android.media.AudioManager manager = (android.media.AudioManager)getSystemService(android.content.Context.AUDIO_SERVICE);
    return manager != null && manager.requestAudioFocus(audioFocusRequest) == android.media.AudioManager.AUDIOFOCUS_REQUEST_GRANTED;
}
